package com.example.nexusgo;

import android.app.Application;
import android.app.NotificationChannel;
import android.app.NotificationManager;
import android.os.Build;
import androidx.appcompat.app.AppCompatDelegate;
import com.example.nexusgo.util.ThemeManager;

public class NexusApp extends Application {
    public static final String CHANNEL_MESSAGES = "messages";
    public static final String CHANNEL_CALLS = "calls";
    public static final String CHANNEL_SERVICE = "service";

    @Override
    public void onCreate() {
        super.onCreate();
        ThemeManager.applyAuto(this);
        createChannels();
    }

    private void createChannels() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            NotificationManager nm = getSystemService(NotificationManager.class);
            nm.createNotificationChannel(new NotificationChannel(
                    CHANNEL_MESSAGES, "Messages", NotificationManager.IMPORTANCE_HIGH));
            NotificationChannel calls = new NotificationChannel(
                    CHANNEL_CALLS, "Calls", NotificationManager.IMPORTANCE_HIGH);
            calls.setBypassDnd(true);
            nm.createNotificationChannel(calls);
            nm.createNotificationChannel(new NotificationChannel(
                    CHANNEL_SERVICE, "Background", NotificationManager.IMPORTANCE_LOW));
        }
    }
}

