package com.example.nexusgo.auth;

import android.content.Intent;
import android.net.Uri;
import android.os.Bundle;
import android.widget.Button;
import android.widget.EditText;
import android.widget.ImageView;
import android.widget.Toast;
import androidx.activity.result.ActivityResultLauncher;
import androidx.activity.result.contract.ActivityResultContracts;
import androidx.appcompat.app.AppCompatActivity;
import com.bumptech.glide.Glide;
import com.example.nexusgo.MainActivity;
import com.example.nexusgo.R;
import com.example.nexusgo.model.User;
import com.example.nexusgo.util.IdGenerator;
import com.google.firebase.auth.FirebaseAuth;
import com.google.firebase.database.FirebaseDatabase;
import com.google.firebase.storage.FirebaseStorage;

public class ProfileSetupActivity extends AppCompatActivity {
    private Uri picUri;
    private ImageView dp;

    @Override
    protected void onCreate(Bundle s) {
        super.onCreate(s);
        setContentView(R.layout.activity_profile_setup);
        EditText name = findViewById(R.id.et_name);
        dp = findViewById(R.id.iv_dp);
        Button pick = findViewById(R.id.btn_pick);
        Button save = findViewById(R.id.btn_save);

        ActivityResultLauncher<String> picker = registerForActivityResult(
                new ActivityResultContracts.GetContent(),
                uri -> { if (uri != null) { picUri = uri; Glide.with(this).load(uri).into(dp); } });
        pick.setOnClickListener(v -> picker.launch("image/*"));

        save.setOnClickListener(v -> {
            String n = name.getText().toString().trim();
            if (n.isEmpty()) { Toast.makeText(this,"Name required",Toast.LENGTH_SHORT).show(); return; }
            String uid = FirebaseAuth.getInstance().getUid();
            String userId = IdGenerator.generate("+91");
            if (picUri != null) {
                FirebaseStorage.getInstance().getReference("dp/" + uid)
                        .putFile(picUri)
                        .continueWithTask(t -> FirebaseStorage.getInstance().getReference("dp/" + uid).getDownloadUrl())
                        .addOnSuccessListener(url -> saveUser(uid, n, userId, url.toString()));
            } else saveUser(uid, n, userId, "");
        });
    }

    private void saveUser(String uid, String name, String userId, String dpUrl) {
        User u = new User(uid, name, userId, dpUrl, System.currentTimeMillis());
        FirebaseDatabase.getInstance().getReference("users").child(uid).setValue(u)
                .addOnSuccessListener(v -> {
                    startActivity(new Intent(this, MainActivity.class));
                    finish();
                });
    }
}

