import androidx.annotation.NonNull;
import androidx.fragment.app.Fragment;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;
import com.example.nexusgo.R;
import com.example.nexusgo.adapter.ChatListAdapter;
import com.example.nexusgo.chat.ChatActivity;
import com.example.nexusgo.friends.AddFriendActivity;
import com.example.nexusgo.model.User;
import com.google.firebase.auth.FirebaseAuth;
import com.google.firebase.database.*;
import java.util.ArrayList;
import java.util.List;

public class ChatsFragment extends Fragment {
    private ChatListAdapter adapter;
    private final List<User> users = new ArrayList<>();

    @Override
    public View onCreateView(@NonNull LayoutInflater i, ViewGroup c, Bundle s) {
        View v = i.inflate(R.layout.fragment_chats, c, false);
        RecyclerView rv = v.findViewById(R.id.rv_chats);
        rv.setLayoutManager(new LinearLayoutManager(getContext()));
        adapter = new ChatListAdapter(users, u -> {
            Intent it = new Intent(getContext(), ChatActivity.class);
            it.putExtra("uid", u.uid);
            it.putExtra("name", u.name);
            startActivity(it);
        });
        rv.setAdapter(adapter);
        v.findViewById(R.id.fab_add).setOnClickListener(x ->
                startActivity(new Intent(getContext(), AddFriendActivity.class)));
        loadFriends();
        return v;
    }

    private void loadFriends() {
        String me = FirebaseAuth.getInstance().getUid();
        if (me == null) return;
        FirebaseDatabase.getInstance().getReference("friends").child(me)
                .addValueEventListener(new ValueEventListener() {
            @Override public void onDataChange(@NonNull DataSnapshot snap) {
                users.clear();
                for (DataSnapshot c : snap.getChildren()) {
                    String uid = c.getKey();
                    FirebaseDatabase.getInstance().getReference("users").child(uid)
                            .get().addOnSuccessListener(s -> {
                                User u = s.getValue(User.class);
                                if (u != null) { users.add(u); adapter.notifyDataSetChanged(); }
                            });
                }
            }
            @Override public void onCancelled(@NonNull DatabaseError e) {}
        });
    }
}

