package com.example.nexusgo.chat;

import android.os.Bundle;
import android.text.Editable;
import android.text.TextWatcher;
import android.view.View;
import android.widget.EditText;
import android.widget.ImageButton;
import android.widget.TextView;
import android.widget.Toast;
import androidx.annotation.NonNull;
import androidx.appcompat.app.AppCompatActivity;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;
import com.example.nexusgo.R;
import com.example.nexusgo.adapter.MessageAdapter;
import com.example.nexusgo.call.CallActivity;
import com.example.nexusgo.model.Message;
import com.google.firebase.auth.FirebaseAuth;
import com.google.firebase.database.*;
import java.util.ArrayList;
import java.util.List;

public class ChatActivity extends AppCompatActivity {
    private String me, peer, chatId;
    private final List<Message> messages = new ArrayList<>();
    private MessageAdapter adapter;
    private DatabaseReference chatRef;
    private DatabaseReference typingRef;

    @Override
    protected void onCreate(Bundle s) {
        super.onCreate(s);
        setContentView(R.layout.activity_chat);
        peer = getIntent().getStringExtra("uid");
        String name = getIntent().getStringExtra("name");
        ((TextView) findViewById(R.id.tv_name)).setText(name);
        me = FirebaseAuth.getInstance().getUid();
        chatId = me.compareTo(peer) < 0 ? me + "_" + peer : peer + "_" + me;
        chatRef = FirebaseDatabase.getInstance().getReference("chats").child(chatId);
        typingRef = FirebaseDatabase.getInstance().getReference("typing").child(chatId);

        RecyclerView rv = findViewById(R.id.rv_messages);
        rv.setLayoutManager(new LinearLayoutManager(this));
        adapter = new MessageAdapter(messages, me, msg -> {
            // undo: delete message if recent
            if (System.currentTimeMillis() - msg.ts < 8000 && msg.from.equals(me)) {
                chatRef.child(msg.id).removeValue();
            }
        });
        rv.setAdapter(adapter);

        EditText et = findViewById(R.id.et_message);
        ImageButton send = findViewById(R.id.btn_send);
        ImageButton ghost = findViewById(R.id.btn_ghost);
        ImageButton call = findViewById(R.id.btn_call);
        ImageButton vcall = findViewById(R.id.btn_vcall);

        et.addTextChangedListener(new TextWatcher() {
            public void beforeTextChanged(CharSequence c, int a, int b, int d) {}
            public void onTextChanged(CharSequence c, int a, int b, int d) {
                typingRef.child(me).setValue(c.length() > 0);
            }
            public void afterTextChanged(Editable e) {}
        });

        ghost.setOnClickListener(v -> {
            typingRef.child(me).setValue(true);
            ghost.postDelayed(() -> typingRef.child(me).setValue(false), 4000);
            Toast.makeText(this, "Ghost typing…", Toast.LENGTH_SHORT).show();
        });

        send.setOnClickListener(v -> {
            String text = et.getText().toString().trim();
            if (text.isEmpty()) return;
            String id = chatRef.push().getKey();
            Message m = new Message(id, me, peer, text, "text",
                    System.currentTimeMillis(), false, false);
            chatRef.child(id).setValue(m);
            et.setText("");
            checkReminder(text);
        });

        call.setOnClickListener(v -> CallActivity.startCall(this, peer, false));
        vcall.setOnClickListener(v -> CallActivity.startCall(this, peer, true));

        listenMessages();
        listenTyping();
    }

    private void listenMessages() {
        chatRef.limitToLast(50).addChildEventListener(new ChildEventListener() {
            public void onChildAdded(@NonNull DataSnapshot snap, String prev) {
                Message m = snap.getValue(Message.class);
                if (m != null) {
                    messages.add(m);
                    adapter.notifyItemInserted(messages.size() - 1);
                    if (m.from.equals(peer) && !m.read) {
                        snap.getRef().child("read").setValue(true);
                    }
                }
            }
            public void onChildChanged(@NonNull DataSnapshot snap, String prev) {
                Message m = snap.getValue(Message.class);
                for (int i = 0; i < messages.size(); i++) {
                    if (messages.get(i).id.equals(m.id)) {
                        messages.set(i, m); adapter.notifyItemChanged(i); break;
                    }
                }
            }
            public void onChildRemoved(@NonNull DataSnapshot snap) {
                String id = snap.getKey();
                for (int i = 0; i < messages.size(); i++) {
                    if (messages.get(i).id.equals(id)) {
                        messages.remove(i); adapter.notifyItemRemoved(i); break;
                    }
                }
            }
            public void onChildMoved(@NonNull DataSnapshot s, String p) {}
            public void onCancelled(@NonNull DatabaseError e) {}
        });
    }

    private void listenTyping() {
        TextView t = findViewById(R.id.tv_typing);
        typingRef.child(peer).addValueEventListener(new ValueEventListener() {
            public void onDataChange(@NonNull DataSnapshot snap) {
                Boolean v = snap.getValue(Boolean.class);
                t.setVisibility(Boolean.TRUE.equals(v) ? View.VISIBLE : View.GONE);
            }
            public void onCancelled(@NonNull DatabaseError e) {}
        });
    }

    private void checkReminder(String text) {
        String low = text.toLowerCase();
        if (low.contains("kal yaad dilana") || low.contains("remind me tomorrow")) {
            Toast.makeText(this, "Reminder set for tomorrow.", Toast.LENGTH_LONG).show();
        }
    }

    @Override protected void onPause() {
        super.onPause();
        typingRef.child(me).setValue(false);
    }
}

