package com.example.nexusgo.adapter;

import android.view.*;
import android.widget.TextView;
import androidx.annotation.NonNull;
import androidx.recyclerview.widget.RecyclerView;
import com.example.nexusgo.R;
import com.example.nexusgo.model.Message;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.List;
import java.util.Locale;

public class MessageAdapter extends RecyclerView.Adapter<MessageAdapter.VH> {
    public interface OnLongClick { void onLong(Message m); }
    private final List<Message> data;
    private final String me;
    private final OnLongClick cb;
    private final SimpleDateFormat fmt = new SimpleDateFormat("HH:mm", Locale.getDefault());

    public MessageAdapter(List<Message> d, String me, OnLongClick c) {
        data = d; this.me = me; cb = c;
    }
    @Override public int getItemViewType(int i) {
        return data.get(i).from.equals(me) ? 1 : 0;
    }
    @NonNull @Override
    public VH onCreateViewHolder(@NonNull ViewGroup p, int t) {
        int layout = t == 1 ? R.layout.item_message_out : R.layout.item_message_in;
        return new VH(LayoutInflater.from(p.getContext()).inflate(layout, p, false));
    }
    @Override public void onBindViewHolder(@NonNull VH h, int i) {
        Message m = data.get(i);
        h.text.setText(m.content);
        h.time.setText(fmt.format(new Date(m.ts)));
        if (h.tick != null) {
            h.tick.setText(m.read ? "✓✓" : (m.delivered ? "✓✓" : "✓"));
            h.tick.setTextColor(m.read ? 0xFF4FC3F7 : 0xFFB0BEC5);
        }
        h.itemView.setOnLongClickListener(v -> { cb.onLong(m); return true; });
    }
    @Override public int getItemCount() { return data.size(); }

    static class VH extends RecyclerView.ViewHolder {
        TextView text, time, tick;
        VH(View v) { super(v);
            text = v.findViewById(R.id.tv_text);
            time = v.findViewById(R.id.tv_time);
            tick = v.findViewById(R.id.tv_tick);
        }
    }
}

