import androidx.appcompat.app.AppCompatActivity;
import com.example.nexusgo.R;
import com.example.nexusgo.webrtc.WebRTCClient;
import com.google.firebase.auth.FirebaseAuth;
import org.webrtc.SurfaceViewRenderer;

public class CallActivity extends AppCompatActivity {
    public static void startCall(Context c, String peerUid, boolean video) {
        Intent i = new Intent(c, CallActivity.class);
        i.putExtra("peer", peerUid);
        i.putExtra("video", video);
        i.putExtra("caller", true);
        c.startActivity(i);
    }

    private WebRTCClient rtc;
    private SurfaceViewRenderer remote, local;

    @Override
    protected void onCreate(Bundle s) {
        super.onCreate(s);
        setContentView(R.layout.activity_call);
        remote = findViewById(R.id.remote_view);
        local = findViewById(R.id.local_view);

        String me = FirebaseAuth.getInstance().getUid();
        String peer = getIntent().getStringExtra("peer");
        boolean video = getIntent().getBooleanExtra("video", false);
        boolean caller = getIntent().getBooleanExtra("caller", false);

        rtc = new WebRTCClient(this, me, peer, video, remote, local);
        if (caller) rtc.startCall(); else rtc.answerCall();

        ImageButton end = findViewById(R.id.btn_end);
        ImageButton mute = findViewById(R.id.btn_mute);
        ImageButton cam = findViewById(R.id.btn_cam);
        ImageButton swap = findViewById(R.id.btn_swap);

        end.setOnClickListener(v -> { rtc.end(); finish(); });
        mute.setOnClickListener(v -> rtc.toggleMute());
        cam.setOnClickListener(v -> rtc.toggleCam());
        swap.setOnClickListener(v -> rtc.switchCamera());

        if (!video) { local.setVisibility(View.GONE); cam.setVisibility(View.GONE); swap.setVisibility(View.GONE); }
    }

    @Override protected void onDestroy() { super.onDestroy(); if (rtc != null) rtc.end(); }
}

