package com.example.nexusgo.webrtc;

import android.content.Context;
import androidx.annotation.NonNull;
import com.google.firebase.database.*;
import org.webrtc.*;
import java.util.ArrayList;
import java.util.List;

public class WebRTCClient {
    private final Context ctx;
    private final String me, peer;
    private final boolean video;
    private final SurfaceViewRenderer remoteView, localView;
    private final EglBase eglBase = EglBase.create();
    private PeerConnectionFactory factory;
    private PeerConnection pc;
    private VideoCapturer capturer;
    private AudioTrack audioTrack;
    private VideoTrack videoTrack;
    private boolean micMuted = false, camOff = false;
    private final String roomId;

    public WebRTCClient(Context c, String me, String peer, boolean video,
                        SurfaceViewRenderer remote, SurfaceViewRenderer local) {
        this.ctx = c.getApplicationContext();
        this.me = me; this.peer = peer; this.video = video;
        this.remoteView = remote; this.localView = local;
        this.roomId = me.compareTo(peer) < 0 ? me + "_" + peer : peer + "_" + me;
        init();
    }

    private void init() {
        PeerConnectionFactory.initialize(PeerConnectionFactory.InitializationOptions
                .builder(ctx).createInitializationOptions());
        factory = PeerConnectionFactory.builder()
                .setVideoEncoderFactory(new DefaultVideoEncoderFactory(eglBase.getEglBaseContext(), true, true))
                .setVideoDecoderFactory(new DefaultVideoDecoderFactory(eglBase.getEglBaseContext()))
                .createPeerConnectionFactory();

        remoteView.init(eglBase.getEglBaseContext(), null);
        if (video) {
            localView.init(eglBase.getEglBaseContext(), null);
            localView.setMirror(true);
        }

        List<PeerConnection.IceServer> ice = new ArrayList<>();
        ice.add(PeerConnection.IceServer.builder("stun:stun.l.google.com:19302").createIceServer());

        pc = factory.createPeerConnection(ice, new PeerConnection.Observer() {
            public void onIceCandidate(IceCandidate c) { sendIce(c); }
            public void onAddStream(MediaStream stream) {
                if (!stream.videoTracks.isEmpty())
                    stream.videoTracks.get(0).addSink(remoteView);
            }
            public void onSignalingChange(PeerConnection.SignalingState s) {}
            public void onIceConnectionChange(PeerConnection.IceConnectionState s) {}
            public void onIceConnectionReceivingChange(boolean b) {}
            public void onIceGatheringChange(PeerConnection.IceGatheringState s) {}
            public void onIceCandidatesRemoved(IceCandidate[] c) {}
            public void onRemoveStream(MediaStream s) {}
            public void onDataChannel(DataChannel d) {}
            public void onRenegotiationNeeded() {}
            public void onAddTrack(RtpReceiver r, MediaStream[] s) {}
        });

        MediaStream local = factory.createLocalMediaStream("local");
        AudioSource as = factory.createAudioSource(new MediaConstraints());
        audioTrack = factory.createAudioTrack("audio", as);
        local.addTrack(audioTrack);

        if (video) {
            capturer = createCameraCapturer();
            SurfaceTextureHelper helper = SurfaceTextureHelper.create("CapTh", eglBase.getEglBaseContext());
            VideoSource vs = factory.createVideoSource(false);
            capturer.initialize(helper, ctx, vs.getCapturerObserver());
            capturer.startCapture(640, 480, 30);
            videoTrack = factory.createVideoTrack("video", vs);
            videoTrack.addSink(localView);
            local.addTrack(videoTrack);
        }
        pc.addStream(local);
        listenSignaling();
    }

    private VideoCapturer createCameraCapturer() {
        Camera2Enumerator e = new Camera2Enumerator(ctx);
        for (String n : e.getDeviceNames()) if (e.isFrontFacing(n))
            return e.createCapturer(n, null);
        for (String n : e.getDeviceNames()) return e.createCapturer(n, null);
        return null;
    }

    public void startCall() {
        MediaConstraints mc = new MediaConstraints();
        pc.createOffer(new SdpAdapter(sdp -> {
            pc.setLocalDescription(new SdpAdapter(null), sdp);
            DatabaseReference r = FirebaseDatabase.getInstance().getReference("calls").child(roomId);
            r.child("offer").setValue(new SdpModel(sdp.type.canonicalForm(), sdp.description));
            r.child("from").setValue(me);
            r.child("to").setValue(peer);
        }), mc);
    }

    public void answerCall() {
        FirebaseDatabase.getInstance().getReference("calls").child(roomId).child("offer")
                .addListenerForSingleValueEvent(new ValueEventListener() {
            public void onDataChange(@NonNull DataSnapshot snap) {
                SdpModel m = snap.getValue(SdpModel.class);
                if (m == null) return;
                pc.setRemoteDescription(new SdpAdapter(null),
                        new SessionDescription(SessionDescription.Type.OFFER, m.sdp));
                pc.createAnswer(new SdpAdapter(sdp -> {
                    pc.setLocalDescription(new SdpAdapter(null), sdp);
                    FirebaseDatabase.getInstance().getReference("calls").child(roomId)
                            .child("answer").setValue(new SdpModel(sdp.type.canonicalForm(), sdp.description));
                }), new MediaConstraints());
            }
            public void onCancelled(@NonNull DatabaseError e) {}
        });
    }

    private void sendIce(IceCandidate c) {
        FirebaseDatabase.getInstance().getReference("calls").child(roomId)
                .child("ice").child(me).push()
                .setValue(new IceModel(c.sdpMid, c.sdpMLineIndex, c.sdp));
    }

    private void listenSignaling() {
        DatabaseReference r = FirebaseDatabase.getInstance().getReference("calls").child(roomId);
        r.child("answer").addValueEventListener(new ValueEventListener() {
            public void onDataChange(@NonNull DataSnapshot s) {
                SdpModel m = s.getValue(SdpModel.class);
                if (m != null && pc.getRemoteDescription() == null)
                    pc.setRemoteDescription(new SdpAdapter(null),
                            new SessionDescription(SessionDescription.Type.ANSWER, m.sdp));
            }
            public void onCancelled(@NonNull DatabaseError e) {}
        });
        r.child("ice").child(peer).addChildEventListener(new ChildEventListener() {
            public void onChildAdded(@NonNull DataSnapshot snap, String prev) {
                IceModel i = snap.getValue(IceModel.class);
                if (i != null) pc.addIceCandidate(new IceCandidate(i.sdpMid, i.sdpMLineIndex, i.sdp));
            }
            public void onChildChanged(@NonNull DataSnapshot s, String p) {}
            public void onChildRemoved(@NonNull DataSnapshot s) {}
            public void onChildMoved(@NonNull DataSnapshot s, String p) {}
            public void onCancelled(@NonNull DatabaseError e) {}
        });
    }

    public void toggleMute() { micMuted = !micMuted; audioTrack.setEnabled(!micMuted); }
    public void toggleCam() { if (videoTrack != null) { camOff = !camOff; videoTrack.setEnabled(!camOff); } }
    public void switchCamera() {
        if (capturer instanceof CameraVideoCapturer)
            ((CameraVideoCapturer) capturer).switchCamera(null);
    }

    public void end() {
        try { if (capturer != null) capturer.stopCapture(); } catch (Exception ignored) {}
        if (pc != null) { pc.close(); pc = null; }
        FirebaseDatabase.getInstance().getReference("calls").child(roomId).removeValue();
    }

    public static class SdpModel {
        public String type, sdp;
        public SdpModel() {}
        public SdpModel(String type, String sdp) { this.type = type; this.sdp = sdp; }
    }
    public static class IceModel {
        public String sdpMid, sdp;
        public int sdpMLineIndex;
        public IceModel() {}
        public IceModel(String sdpMid, int idx, String sdp) {
            this.sdpMid = sdpMid; this.sdpMLineIndex = idx; this.sdp = sdp;
        }
    }
}

