package com.example.nexusgo.service;

import android.app.PendingIntent;
import android.content.Intent;
import androidx.annotation.NonNull;
import androidx.core.app.NotificationCompat;
import androidx.core.app.NotificationManagerCompat;
import com.example.nexusgo.NexusApp;
import com.example.nexusgo.R;
import com.example.nexusgo.call.IncomingCallActivity;
import com.google.firebase.auth.FirebaseAuth;
import com.google.firebase.database.FirebaseDatabase;
import com.google.firebase.messaging.FirebaseMessagingService;
import com.google.firebase.messaging.RemoteMessage;
import java.util.Map;

public class NexusFirebaseMessagingService extends FirebaseMessagingService {

    @Override public void onNewToken(@NonNull String token) {
        String uid = FirebaseAuth.getInstance().getUid();
        if (uid != null)
            FirebaseDatabase.getInstance().getReference("tokens").child(uid).setValue(token);
    }

    @Override public void onMessageReceived(@NonNull RemoteMessage msg) {
        Map<String, String> d = msg.getData();
        String type = d.get("type");
        if ("call".equals(type)) {
            Intent i = new Intent(this, IncomingCallActivity.class);
            i.putExtra("peer", d.get("from"));
            i.putExtra("video", "true".equals(d.get("video")));
            i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
            PendingIntent p = PendingIntent.getActivity(this, 0, i,
                    PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);
            NotificationCompat.Builder b = new NotificationCompat.Builder(this, NexusApp.CHANNEL_CALLS)
                    .setSmallIcon(R.mipmap.ic_launcher)
                    .setContentTitle("Incoming call")
                    .setContentText("Tap to answer")
                    .setFullScreenIntent(p, true)
                    .setPriority(NotificationCompat.PRIORITY_HIGH)
                    .setCategory(NotificationCompat.CATEGORY_CALL)
                    .setAutoCancel(true);
            try { NotificationManagerCompat.from(this).notify(99, b.build()); }
            catch (SecurityException ignored) {}
        } else {
            NotificationCompat.Builder b = new NotificationCompat.Builder(this, NexusApp.CHANNEL_MESSAGES)
                    .setSmallIcon(R.mipmap.ic_launcher)
                    .setContentTitle(d.getOrDefault("title", "New message"))
                    .setContentText(d.getOrDefault("body", ""))
                    .setAutoCancel(true);
            try { NotificationManagerCompat.from(this).notify((int)(System.currentTimeMillis()&0xfffffff), b.build()); }
            catch (SecurityException ignored) {}
        }
    }
}

